/// Translate a Gemma route into an xray outbound JSON fragment.
fn route_to_outbound(footprint: &str, trace_id: &str, route: &XrayRoute) -> Option<String> {
    let tag = &route.tag;
    match &route.backend {
        GemmaBackend::Ingress => None,
        GemmaBackend::Tcp { host, port } => Some(format!(
            r#",
    {{
      "tag": "to-{tag}",
      "protocol": "freedom",
      "settings": {{ "redirect": "{host}:{port}" }}
    }}"#
        )),
        GemmaBackend::Grpc {
            host,
            port,
            service_name,
        } => Some(format!(
            r#",
    {{
      "tag": "to-{tag}",
      "protocol": "freedom",
      "settings": {{ "redirect": "{host}:{port}" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "{service_name}",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }}"#,
            tag = tag,
            host = host,
            port = port,
            service_name = service_name,
            footprint = footprint,
            trace_id = trace_id,
        )),
        GemmaBackend::Unix { path: _ } => Some(format!(
            r#",
    {{
      "tag": "to-{tag}",
      "protocol": "freedom",
      "settings": {{ "redirect": "{host}:{port}" }},
      "streamSettings": {{
        "network": "grpc",
        "sockopt": {{ "tcpNoDelay": true, "mark": 255 }},
        "grpcSettings": {{
          "serviceName": "Ghostbridge.{tag}",
          "multiMode": true,
          "metadata": {{
            "X-Ghostbridge-Footprint": "{footprint}",
            "X-Ghostbridge-Trace-ID": "{trace_id}"
          }}
        }}
      }}
    }}"#,
            tag = tag,
            host = GRPC_BRIDGE_HOST,
            port = GRPC_BRIDGE_PORT,
            footprint = footprint,
            trace_id = trace_id,
        )),
        GemmaBackend::Dns { host, port } => Some(format!(
            r#",
    {{
      "tag": "to-{tag}",
      "protocol": "freedom",
      "settings": {{ "redirect": "{host}:{port}" }}
    }}"#,
            tag = tag,
            host = host,
            port = port,
        )),
        GemmaBackend::File { .. } | GemmaBackend::Internal => None,
    }
}

