#[async_trait]
impl Tool for CodeContextTool {
    fn name(&self) -> &str {
        "code_context"
    }

    fn description(&self) -> &str {
        "Session-aware coding context. Records the current activity (query, edit, build_error, \
         test_failure, etc.) into the awareness engine, runs fused retrieval, and returns relevant \
         code plus session signals (stuck, recent errors, topics)."
    }

    fn category(&self) -> &str {
        "code"
    }

    fn tags(&self) -> Vec<String> {
        vec!["code".into(), "context".into(), "session".into()]
    }

    fn input_schema(&self) -> Value {
        tool_input_schema("code_context")
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let query = input
            .get("query")
            .and_then(Value::as_str)
            .ok_or_else(|| anyhow::anyhow!("missing query"))?;
        let session_id = input
            .get("session_id")
            .and_then(Value::as_str)
            .unwrap_or("default");
        let activity_type = input
            .get("activity_type")
            .and_then(Value::as_str)
            .map(ActivityType::parse)
            .unwrap_or(ActivityType::Query);
        let profile = retrieval_profile_from(&input, RetrievalMode::Completion);
        let limit = input
            .get("limit")
            .and_then(Value::as_u64)
            .unwrap_or(profile.limit)
            .clamp(1, 50);

        // Record the activity so stuck/error/topic detection stays current.
        self.engine
            .record_activity(
                session_id,
                activity_type,
                query.to_string(),
                serde_json::json!({ "source": "code_context" }),
            )
            .await;

        let filter = filter_from(&input, false);
        let collections = collections_from(&input, &self.collection, &profile);
        let (results, retrieval_error) = match self
            .rag
            .query_fused_collections(&collections, query, limit, profile.fetch_limit, &filter)
            .await
        {
            Ok(results) => (results, None),
            Err(err) => {
                warn!(
                    error = %err,
                    "Code-context vector retrieval unavailable; returning awareness signals only"
                );
                (Vec::new(), Some(err.to_string()))
            }
        };

        let signals = self
            .engine
            .get_session_signals(session_id)
            .await
            .unwrap_or_else(|| serde_json::json!({ "session_id": session_id }));

        Ok(json!({
            "count": results.len(),
            "collections": collections,
            "retrieval_mode": profile.mode.as_str(),
            "rerank_enabled": profile.rerank_enabled,
            "kiro_lsp_state_dir": profile.kiro_lsp_state_dir,
            "session_id": session_id,
            "signals": serde_to_simd(&signals),
            "results": results_to_simd(&results),
            "retrieval_error": retrieval_error,
        }))
    }
}

// ─── code_index ─────────────────────────────────────────────────────────────

pub struct CodeIndexTool {
    rag: Arc<RagPipeline>,
    collection: String,
}

#[async_trait]
impl Tool for CodeIndexTool {
    fn name(&self) -> &str {
        "code_index"
    }

    fn description(&self) -> &str {
        "Index code into the semantic store. mode='source' indexes a single in-memory file \
         (repo, file_path, content) for live workspace updates; mode='repomix_zip' ingests an \
         entry from a repomix zip (zip_path, entry)."
    }

    fn category(&self) -> &str {
        "code"
    }

    fn tags(&self) -> Vec<String> {
        vec!["code".into(), "index".into(), "ingest".into()]
    }

    fn input_schema(&self) -> Value {
        tool_input_schema("code_index")
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let collection = input
            .get("collection")
            .and_then(Value::as_str)
            .unwrap_or(&self.collection);
        let mode = input
            .get("mode")
            .and_then(Value::as_str)
            .unwrap_or("source");

        let stats = match mode {
            "source" => {
                let repo = input
                    .get("repo")
                    .and_then(Value::as_str)
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'repo'"))?;
                let file_path = input
                    .get("file_path")
                    .and_then(Value::as_str)
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'file_path'"))?;
                let content = input
                    .get("content")
                    .and_then(Value::as_str)
                    .ok_or_else(|| anyhow::anyhow!("source mode requires 'content'"))?;
                self.rag
                    .ingest_source_text(repo, file_path, content, collection)
                    .await?
            }
            "repomix_zip" => {
                let zip_path = input
                    .get("zip_path")
                    .and_then(Value::as_str)
                    .ok_or_else(|| anyhow::anyhow!("repomix_zip mode requires 'zip_path'"))?;
                let entry = input
                    .get("entry")
                    .and_then(Value::as_str)
                    .ok_or_else(|| anyhow::anyhow!("repomix_zip mode requires 'entry'"))?;
                self.rag
                    .ingest_repomix_entry(&PathBuf::from(zip_path), entry, collection)
                    .await?
            }
            other => return Err(anyhow::anyhow!("unknown mode: {other}")),
        };

        Ok(json!({
            "ok": true,
            "mode": mode,
            "collection": collection,
            "files_parsed": stats.files_parsed as u64,
            "chunks_created": stats.chunks_created as u64,
            "chunks_upserted": stats.chunks_upserted as u64,
            "chunks_skipped": stats.chunks_skipped as u64,
            "errors": stats.errors as u64,
        }))
    }
}

// ─── helpers ──────────────────────────────────────────────────────────────────

/// Derive a tool's JSON input schema from the single canonical authority
/// (`op_plugins::cognitive_mcp_plugin_schema`). The tool never declares its
/// schema inline — the OSCAL subid and field contract live in the PluginSchema.
fn tool_input_schema(field: &str) -> Value {
    op_plugins::cognitive_mcp_plugin_schema()
        .field_input_schema(field)
        .unwrap_or_else(|| json!({ "type": "object", "properties": {} }))
}

fn filter_from(input: &Value, default_exclude_tests: bool) -> CodeFilter {
    CodeFilter {
        repo: input.get("repo").and_then(Value::as_str).map(String::from),
        language: input
            .get("language")
            .and_then(Value::as_str)
            .map(String::from),
        file_type: input
            .get("file_type")
            .and_then(Value::as_str)
            .map(String::from),
        path_contains: input
            .get("path_contains")
            .and_then(Value::as_str)
            .map(String::from),
        symbol_contains: input
            .get("symbol_contains")
            .and_then(Value::as_str)
            .map(String::from),
        exclude_tests: input
            .get("exclude_tests")
            .and_then(Value::as_bool)
            .unwrap_or(default_exclude_tests),
    }
}

fn retrieval_profile_from(input: &Value, default_mode: RetrievalMode) -> RetrievalProfile {
    let mode = input
        .get("retrieval_mode")
        .or_else(|| input.get("mode"))
        .and_then(Value::as_str)
        .map(RetrievalMode::parse)
        .unwrap_or(default_mode);
    RetrievalProfile::from_env(mode)
}

fn collections_from(input: &Value, fallback: &str, profile: &RetrievalProfile) -> Vec<String> {
    if let Some(collection) = input.get("collection").and_then(Value::as_str) {
        return vec![collection.to_string()];
    }

    if let Some(collections) = input.get("collections").and_then(Value::as_array) {
        let parsed: Vec<String> = collections
            .iter()
            .filter_map(Value::as_str)
            .map(String::from)
            .collect();
        if !parsed.is_empty() {
            return parsed;
        }
    }

    if !profile.collections.is_empty() {
        return profile.collections.clone();
    }

    vec![fallback.to_string()]
}

fn results_to_simd(results: &[RagResult]) -> Value {
    let serde_val = serde_json::to_value(results).unwrap_or(serde_json::Value::Null);
    serde_to_simd(&serde_val)
}

fn serde_to_simd(v: &serde_json::Value) -> Value {
    let s = serde_json::to_string(v).unwrap_or_default();
    let mut buf = s.into_bytes();
    simd_json::from_slice(&mut buf).unwrap_or(Value::Static(simd_json::StaticNode::Null))
}

//! Cognitive MCP Server Binary
//!
//! Transports started in parallel:
//! - HTTP/SSE  (MCP protocol, port 3003)
//! - gRPC      (CognitiveToolService, port 50052)
//! - D-Bus state is owned by the canonical plugin projection at
//!   org.opdbus.v1.plugins / /org/opdbus/v1/plugins/cognitive_mcp
//!
//! On startup the server reads the local WireGuard public key (from the
//! interface named by $WG_INTERFACE, defaulting to "netmaker") and writes the
//! canonical IdentitySled to /dev/shm/plugin_schema.dat so the Ghostbridge
//! interceptor and Qdrant shuttle can authenticate outbound gRPC calls.
//!
//! Bind address resolution order (highest priority first):
//!   1. COGNITIVE_MCP_BIND / COGNITIVE_MCP_GRPC_BIND env vars
//!   2. --http / --grpc CLI flags
//!   3. WireGuard interface IP detected at startup (if interface is up)
//!   4. 0.0.0.0 fallback

use clap::Parser;
use op_cognitive_mcp::CognitiveMcpServer;
use op_identity::{write_sled_from_wg, WireGuardIdentity};
use tracing::{info, warn, Level};
use tracing_subscriber::FmtSubscriber;

#[derive(Parser)]
#[command(name = "cognitive-mcp-server")]
#[command(about = "Cognitive MCP Server with memory, NotebookLM bridge, HTTP, and gRPC")]
struct Cli {
    /// HTTP/SSE server address (MCP protocol).
    /// If left at 0.0.0.0 the WireGuard interface IP is used when available.
    /// Override with COGNITIVE_MCP_BIND env var or this flag.
    #[arg(long, env = "COGNITIVE_MCP_BIND", default_value = "0.0.0.0:3003")]
    http: String,

    /// gRPC server address (CognitiveToolService).
    /// If left at 0.0.0.0 the WireGuard interface IP is used when available.
    /// Override with COGNITIVE_MCP_GRPC_BIND env var or this flag.
    #[arg(long, env = "COGNITIVE_MCP_GRPC_BIND", default_value = "0.0.0.0:50052")]
    grpc: String,

    /// CozoDB database path
    #[arg(
        long,
        env = "COGNITIVE_MCP_DB_PATH",
        default_value = "/var/lib/op-cognitive-mcp/memory.db"
    )]
    db: String,

    /// WireGuard interface to read identity from
    #[arg(long, env = "WG_INTERFACE", default_value = "netmaker")]
    wg_interface: String,

    /// Log level
    #[arg(long, env = "COGNITIVE_MCP_LOG_LEVEL", default_value = "info")]
    log_level: String,

    /// Disable gRPC server
    #[arg(long, env = "COGNITIVE_MCP_GRPC_DISABLED")]
    no_grpc: bool,

    /// Disable HTTP/SSE server
    #[arg(long, env = "COGNITIVE_MCP_HTTP_DISABLED")]
    no_http: bool,

    /// Run stdio transport only (for local MCP clients — direct, no network)
    #[arg(long, env = "COGNITIVE_MCP_STDIO")]
    stdio: bool,
}

/// Promote an `0.0.0.0:PORT` default address to `<wg_ip>:PORT` when the WG
/// interface is up.  Explicit addresses (not starting with `0.0.0.0:`) are
/// returned unchanged so env-var or flag overrides always win.
fn resolve_bind(addr: &str, wg_ip: Option<&str>) -> String {
    if let Some(rest) = addr.strip_prefix("0.0.0.0:") {
        if let Some(ip) = wg_ip {
            return format!("{ip}:{rest}");
        }
    }
    addr.to_string()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    let level = match cli.log_level.as_str() {
        "trace" => Level::TRACE,
        "debug" => Level::DEBUG,
        "warn" => Level::WARN,
        "error" => Level::ERROR,
        _ => Level::INFO,
    };

    let subscriber = FmtSubscriber::builder()
        .with_max_level(level)
        .with_writer(std::io::stderr)
        .finish();
    tracing::subscriber::set_global_default(subscriber)?;

    // ── WireGuard identity ────────────────────────────────────────────────────
    // 1. Detect local WG IP for bind address resolution.
    // 2. Write canonical IdentitySled to /dev/shm for Ghostbridge auth.
    let wg_id = WireGuardIdentity::with_interface(&cli.wg_interface);
    let wg_ip = wg_id.get_local_ip();

    match wg_id.get_local_pubkey() {
        Ok(pubkey) => {
            info!(
                interface = %cli.wg_interface,
                pubkey = %pubkey,
                wg_ip = ?wg_ip,
                "Writing WireGuard identity sled to /dev/shm/plugin_schema.dat"
            );
            if let Err(e) = write_sled_from_wg(&pubkey) {
                warn!(
                    error = %e,
                    "Failed to write identity sled — gRPC Ghostbridge auth will not work"
                );
            }
        }
        Err(e) => {
            warn!(
                interface = %cli.wg_interface,
                error = %e,
                "Could not read WireGuard public key — identity sled not written; \
                 set WG_PUBKEY env var to override"
            );
        }
    }

    // Resolve bind addresses: promote 0.0.0.0 defaults to WG interface IP.
    let http_addr = resolve_bind(&cli.http, wg_ip.as_deref());
    let grpc_addr = resolve_bind(&cli.grpc, wg_ip.as_deref());

    info!(
        http = %http_addr,
        grpc = %grpc_addr,
        db = %cli.db,
        wg_interface = %cli.wg_interface,
        "Starting Cognitive MCP Server"
    );

    let server = CognitiveMcpServer::new(&cli.db).await?;

    if cli.stdio {
        info!("Running stdio only (local MCP transport)");
        server.start_stdio().await?;
        return Ok(());
    }

    match (cli.no_grpc, cli.no_http) {
        (true, true) => {
            eprintln!("Error: both --no-grpc and --no-http specified. Nothing to run.");
            std::process::exit(1);
        }
        (true, false) => {
            info!("Running HTTP/SSE only");
            server.start_http_server(&http_addr).await?;
        }
        (false, true) => {
            info!("Running gRPC only");
            server.start_grpc_server(&grpc_addr).await?;
        }
        (false, false) => {
            info!("Running HTTP/SSE + gRPC");
            server.start_dual(&http_addr, &grpc_addr).await?;
        }
    }

    Ok(())
}

//! Cognitive MCP Server — Dual Transport (HTTP/SSE + gRPC)
//!
//! Single persistent backend (CozoDB) hosts every relation:
//! memory namespaces/entries, users, sessions, compliance graph, subid registry, audit log.

use crate::code_tools::register_code_tools;
use crate::cognitive_tools::CognitiveToolRegistry;
use crate::context_awareness::{ContextAwarenessConfig, ContextAwarenessEngine};
use crate::cozo_shuttle::CozoGraphShuttle;
use crate::gemini_fallback::GeminiFallback;
use crate::grpc_service::CognitiveGrpcService;
use crate::memory_store::CognitiveMemoryStore;
use crate::proto::cognitive_tool_service_server::CognitiveToolServiceServer;
use crate::qdrant_shuttle::QdrantSemanticShuttle;
use crate::quota::QuotaManager;
use crate::rag_pipeline::{default_collection_from_env, RagPipeline};
use crate::session::SessionManager;
use crate::typed_tools;
use op_mcp::tool_registry::{RegistryExecutor, ToolRegistry};
use std::path::PathBuf;
use std::sync::Arc;

pub struct CognitiveMcpServer {
    memory_store: Arc<CognitiveMemoryStore>,
    cozo_shuttle: Arc<CozoGraphShuttle>,
    qdrant_shuttle: Option<Arc<QdrantSemanticShuttle>>,
    tool_registry: Arc<ToolRegistry>,
    session_manager: Arc<SessionManager>,
    quota_manager: Arc<QuotaManager>,
    gemini_fallback: Arc<GeminiFallback>,
    /// Code-RAG pipeline (Voyage + Qdrant). `None` when no Voyage key is found.
    rag_pipeline: Option<Arc<RagPipeline>>,
    /// Proactive coding-context awareness engine.
    context_engine: Arc<ContextAwarenessEngine>,
}

impl CognitiveMcpServer {
    /// `db_path` is the CozoDB directory backing every persistent relation
    /// (memory namespaces/entries, users, sessions, compliance graph, audit log).
    pub async fn new(db_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let cozo_shuttle = Arc::new(CozoGraphShuttle::new_persistent(PathBuf::from(db_path))?);
        let memory_store = Arc::new(CognitiveMemoryStore::new(cozo_shuttle.clone()).await?);

        let tool_registry = Arc::new(ToolRegistry::new());

        let qdrant_shuttle = match QdrantSemanticShuttle::new().await {
            Ok(shuttle) => Some(Arc::new(shuttle)),
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    "Qdrant Semantic Shuttle unavailable; cognitive MCP will continue without vector retrieval"
                );
                None
            }
        };

        let session_manager = Arc::new(SessionManager::with_defaults());
        let quota_manager = Arc::new(QuotaManager::with_defaults());
        let gemini_fallback = Arc::new(GeminiFallback::new());

        CognitiveToolRegistry::register_all(&tool_registry, memory_store.clone()).await?;

        typed_tools::register_typed_tools(
            &tool_registry,
            memory_store.clone(),
            session_manager.clone(),
            quota_manager.clone(),
        )
        .await?;

        // Code-RAG pipeline: optional, like qdrant_shuttle. Without a Voyage key
        // (env or ~/.ssh/mongo-voyage) the cognitive MCP still serves memory tools.
        let rag_pipeline = match RagPipeline::from_env() {
            Ok(p) => Some(Arc::new(p)),
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    "RAG pipeline unavailable; code-context tools will not be registered"
                );
                None
            }
        };

        // Context-awareness engine drives session signals and proactive pushes.
        let rag_collection = default_collection_from_env();
        let context_engine = Arc::new(ContextAwarenessEngine::new(
            ContextAwarenessConfig {
                rag_collection: rag_collection.clone(),
                ..Default::default()
            },
            memory_store.clone(),
            rag_pipeline.clone(),
        ));
        context_engine.clone().start_monitoring();

        if let Some(rag) = &rag_pipeline {
            let n = register_code_tools(
                &tool_registry,
                rag.clone(),
                context_engine.clone(),
                rag_collection,
            )
            .await?;
            tracing::info!(registered = n, "Registered code-context tools");
        }

        Ok(Self {
            memory_store,
            cozo_shuttle,
            qdrant_shuttle,
            tool_registry,
            session_manager,
            quota_manager,
            gemini_fallback,
            rag_pipeline,
            context_engine,
        })
    }

    /// Run the cognitive MCP server over stdio (stdin/stdout JSON-RPC).
    /// This is the preferred transport for local MCP clients — no network
    /// overhead, direct pipe communication.
    pub async fn start_stdio(self) -> Result<(), Box<dyn std::error::Error>> {
        use op_mcp::{McpServer, McpServerConfig, StdioTransport, Transport};

        let config = McpServerConfig {
            name: Some("cognitive-mcp".to_string()),
            compact_mode: false,
            ..Default::default()
        };

        let executor = Arc::new(RegistryExecutor::new(self.tool_registry.clone()));
        let mcp_server = Arc::new(McpServer::with_executor(config, executor));

        tracing::info!("Cognitive MCP Server starting (stdio transport)");

        StdioTransport::new().serve(mcp_server).await?;
        Ok(())
    }

    pub async fn start_http_server(self, addr: &str) -> Result<(), Box<dyn std::error::Error>> {
        use crate::context_server::build_context_router;
        use op_mcp::{HttpSseTransport, McpServer, McpServerConfig, Transport};

        let config = McpServerConfig {
            name: Some("cognitive-mcp".to_string()),
            compact_mode: false,
            ..Default::default()
        };

        let executor = Arc::new(RegistryExecutor::new(self.tool_registry.clone()));
        let mcp_server = Arc::new(McpServer::with_executor(config, executor));

        let mut transport = HttpSseTransport::new(addr.to_string());
        if std::env::var("COGNITIVE_MCP_CONTEXT_HTTP_DISABLED").as_deref() != Ok("1") {
            // Mount the context-awareness SSE endpoints on the same HTTP server
            // so they share auth, CORS, and the port with the MCP protocol routes.
            let context_router = build_context_router(
                self.context_engine.clone(),
                self.memory_store.clone(),
                self.session_manager.clone(),
            );
            transport = transport.with_extra_router(context_router);
        }

        tracing::info!(
            addr = %addr,
            "Cognitive MCP Server listening (MCP + context-awareness endpoints)"
        );
        transport.serve(mcp_server).await?;
        Ok(())
    }

    pub async fn start_grpc_server(&self, addr: &str) -> Result<(), Box<dyn std::error::Error>> {
        let grpc_service = CognitiveGrpcService::new(
            self.memory_store.clone(),
            self.session_manager.clone(),
            self.quota_manager.clone(),
            self.gemini_fallback.clone(),
        );

        let reflection = tonic_reflection::server::Builder::configure()
            .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
            .build_v1()
            .expect("failed to build cognitive reflection service");

        let (mut health_reporter, health_service) = tonic_health::server::health_reporter();
        health_reporter
            .set_serving::<CognitiveToolServiceServer<CognitiveGrpcService>>()
            .await;

        let socket_addr: std::net::SocketAddr = addr.parse()?;
        tracing::info!(addr = %socket_addr, "Cognitive gRPC Server listening");

        let cors = tower_http::cors::CorsLayer::new()
            .allow_origin(tower_http::cors::Any)
            .allow_methods(tower_http::cors::Any)
            .allow_headers(tower_http::cors::Any)
            .expose_headers([
                "grpc-status".parse().unwrap(),
                "grpc-message".parse().unwrap(),
                "grpc-status-details-bin".parse().unwrap(),
            ]);

        tonic::transport::Server::builder()
            .accept_http1(true)
            .layer(cors)
            .add_service(tonic_web::enable(
                CognitiveToolServiceServer::with_interceptor(
                    grpc_service,
                    crate::interceptor::ghostbridge_interceptor,
                ),
            ))
            .add_service(tonic_web::enable(reflection))
            .add_service(tonic_web::enable(health_service))
            .serve(socket_addr)
            .await?;

        Ok(())
    }

    pub async fn start_dual(
        self,
        http_addr: &str,
        grpc_addr: &str,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let grpc_addr = grpc_addr.to_string();
        let http_addr = http_addr.to_string();

        let grpc_memory = self.memory_store.clone();
        let grpc_session = self.session_manager.clone();
        let grpc_quota = self.quota_manager.clone();
        let grpc_gemini = self.gemini_fallback.clone();

        let grpc_handle = tokio::spawn(async move {
            let grpc_service =
                CognitiveGrpcService::new(grpc_memory, grpc_session, grpc_quota, grpc_gemini);

            let reflection = tonic_reflection::server::Builder::configure()
                .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
                .build_v1()
                .expect("failed to build cognitive reflection service");

            let (mut health_reporter, health_service) = tonic_health::server::health_reporter();
            health_reporter
                .set_serving::<CognitiveToolServiceServer<CognitiveGrpcService>>()
                .await;

            let socket_addr: std::net::SocketAddr = grpc_addr.parse().expect("invalid gRPC addr");
            tracing::info!(addr = %socket_addr, "Cognitive gRPC Server listening");

            let cors = tower_http::cors::CorsLayer::new()
                .allow_origin(tower_http::cors::Any)
                .allow_methods(tower_http::cors::Any)
                .allow_headers(tower_http::cors::Any)
                .expose_headers([
                    "grpc-status".parse().unwrap(),
                    "grpc-message".parse().unwrap(),
                    "grpc-status-details-bin".parse().unwrap(),
                ]);

            tonic::transport::Server::builder()
                .accept_http1(true)
                .layer(cors)
                .add_service(tonic_web::enable(
                    CognitiveToolServiceServer::with_interceptor(
                        grpc_service,
                        crate::interceptor::ghostbridge_interceptor,
                    ),
                ))
                .add_service(tonic_web::enable(reflection))
                .add_service(tonic_web::enable(health_service))
                .serve(socket_addr)
                .await
                .expect("gRPC server failed");
        });

        self.start_http_server(&http_addr).await?;
        grpc_handle.await?;
        Ok(())
    }

    pub fn memory_store(&self) -> Arc<CognitiveMemoryStore> {
        self.memory_store.clone()
    }

    pub fn cozo_shuttle(&self) -> Arc<CozoGraphShuttle> {
        self.cozo_shuttle.clone()
    }

    pub fn tool_registry(&self) -> Arc<ToolRegistry> {
        self.tool_registry.clone()
    }

    pub fn qdrant_shuttle(&self) -> Option<Arc<QdrantSemanticShuttle>> {
        self.qdrant_shuttle.clone()
    }

    pub fn session_manager(&self) -> Arc<SessionManager> {
        self.session_manager.clone()
    }

    pub fn quota_manager(&self) -> Arc<QuotaManager> {
        self.quota_manager.clone()
    }

    pub fn rag_pipeline(&self) -> Option<Arc<RagPipeline>> {
        self.rag_pipeline.clone()
    }

    pub fn context_engine(&self) -> Arc<ContextAwarenessEngine> {
        self.context_engine.clone()
    }
}

//! CozoDB relational-graph-vector database plugin.
//!
//! Schema derived from CozoDB official documentation (docs.cozodb.org/en/latest/).
//! CozoDB is a Datalog database with dynamic schema — relations are created with
//! `:create` specifying key/value columns and types. The system exposes metadata
//! via `::relations`, `::columns`, `::indices` system ops.
//!
//! Column types (from docs.cozodb.org/en/latest/datatypes.html):
//!   Atomic: Int, Float, Bool, String, Bytes, Uuid, Json, Validity
//!   Composite: [Type] (list), (T1, T2) (tuple), <F32; N> (vector)
//!   Special: Any, Any? (nullable)
//!
//! Engines: mem, sled, rocksdb, sqlite
//! Access levels: normal, protected, read_only, hidden

use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

/// CozoDB column definition — mirrors `::columns` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoColumn {
    pub name: String,
    pub r#type: String,     // Int, Float, Bool, String, Bytes, Uuid, Json, Validity, Any, Any?
    pub is_key: bool,       // true if before => in :create spec
    pub default: Option<String>,
    pub description: String,
}

/// CozoDB index definition — mirrors `::indices` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoIndex {
    pub name: String,       // e.g. "relation_name:index_name"
    pub relation: String,
    pub columns: Vec<String>,
}

/// CozoDB trigger — mirrors `::show_triggers` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoTrigger {
    pub relation: String,
    pub event: String,      // "put", "rm", "replace"
    pub query: String,
}

/// CozoDB stored relation — mirrors `::relations` + `::columns` system op output.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoRelation {
    pub name: String,
    pub description: String,
    pub keys: Vec<CozoColumn>,
    pub values: Vec<CozoColumn>,
    pub access_level: String, // normal, protected, read_only, hidden
    pub row_count: Option<u64>,
}

/// CozoDB HNSW vector index — from docs.cozodb.org/en/latest/vector.html
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoHnswIndex {
    pub name: String,
    pub relation: String,
    pub vector_column: String,
    pub dim: u32,
    pub dtype: String,      // "f32" or "f64"
    pub m: u32,
    pub ef_construction: u32,
    pub ef_search: u32,
    pub distance: String,   // "Cosine", "Euclid", "Dot"
}

/// Top-level CozoDB plugin state — the shape the projection tree exposes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CozoState {
    pub engine: String,         // mem, sled, rocksdb, sqlite
    pub path: String,           // database path (empty for mem)
    pub version: String,        // CozoDB version
    pub relations: Vec<CozoRelation>,
    pub indices: Vec<CozoIndex>,
    pub hnsw_indices: Vec<CozoHnswIndex>,
    pub triggers: Vec<CozoTrigger>,
    pub running_queries: u32,
}

pub struct CozoPlugin;

impl Default for CozoPlugin {
    fn default() -> Self {
        Self
    }
}

impl CozoPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Exemplar state derived from CozoDB docs system ops structure.
    /// Field names and types match the `::relations`, `::columns`, `::indices`
    /// system op outputs and the datatypes reference.
    pub(crate) fn exemplar_state() -> CozoState {
        CozoState {
