impl KnowledgePlugin {
    pub fn new() -> Self {
        Self
    }
    fn qdrant_endpoint() -> String {
        std::env::var("COGNITIVE_MCP_QDRANT_URL")
            .or_else(|_| std::env::var("QDRANT_URL"))
            .unwrap_or_else(|_| DEFAULT_QDRANT_ENDPOINT.to_string())
    }

    /// Data directory of the in-process CozoDB graph store. Cozo is embedded in
    /// the bridge (op-cozo-store `CozoGraphShuttle`), reached over gRPC — there
    /// is no separate cozoserver endpoint to probe.
    fn cozo_datadir() -> String {
        std::env::var("COGNITIVE_MCP_COZO_DB_PATH")
            .unwrap_or_else(|_| DEFAULT_COZO_DATADIR.to_string())
    }

    fn endpoint_tcp_addr(endpoint: &str) -> Option<String> {
        let stripped = endpoint
            .strip_prefix("http://")
            .or_else(|| endpoint.strip_prefix("https://"))
            .unwrap_or(endpoint);
        let host_port = stripped.split('/').next()?;
        if host_port.contains(':') {
            Some(host_port.to_string())
        } else {
            None
        }
    }

    fn qdrant_reachable(endpoint: &str) -> bool {
        let addr = match Self::endpoint_tcp_addr(endpoint) {
            Some(addr) => addr,
            None => return false,
        };
        let socket_addr = match addr.parse() {
            Ok(addr) => addr,
            Err(_) => return false,
        };
        TcpStream::connect_timeout(&socket_addr, Duration::from_millis(750)).is_ok()
    }

    pub(crate) fn current_state() -> KnowledgeState {
        let qdrant_endpoint = Self::qdrant_endpoint();
        let cozo_datadir = Self::cozo_datadir();
        KnowledgeState {
            status: "active".to_string(),
            stores: json!([{"name": "qdrant", "type": "vector", "status": "unknown", "endpoint": qdrant_endpoint, "collections": [], "dimensions": 1024}, {"name": "cozo", "type": "graph", "status": "embedded", "engine": "rocksdb", "datadir": cozo_datadir, "relations": 0, "stored_procedure_count": 0}, {"name": "sled", "type": "kv", "status": "active", "path": "/dev/shm/plugin_schema.dat"}]),
