        ("infrastructure", &["docker", "kubernetes", "deploy", "server", "s6"]),
        ("security", &["auth", "encrypt", "token", "vulnerability", "oauth"]),
        ("rust", &["cargo", "trait", "impl", "async", "tokio", "rustc"]),
