#[cfg(test)]
mod tests {
    use super::*;

    fn registry_entry(
        subid: &str,
        subject: &str,
        tag: &str,
        subdomains: Vec<&str>,
        backend: BackendSpec,
    ) -> RegistryEntry {
        RegistryEntry {
            uuid: format!("uuid-{subid}"),
            subid: subid.to_string(),
            category: "exp".to_string(),
            component_type: "service".to_string(),
            subject: subject.to_string(),
            verb: "serve".to_string(),
            version: 1,
            tags: vec![tag.to_string()],
            subdomains: subdomains.into_iter().map(String::from).collect(),
            gemma: Some(GemmaConfig { backend }),
        }
    }

    #[test]
    fn should_dedupe_duplicate_subdomains_first_route_wins() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.zeroclaw-serve@v1",
                    "zeroclaw",
                    "grpc-bridge",
                    vec!["assistant.ghostbridge.tech"],
                    BackendSpec::Grpc {
                        host: "127.0.0.1".into(),
                        port: 18789,
                        service_name: "Ghostbridge.StateSync".into(),
                    },
                ),
                registry_entry(
                    "exp.service.zeroclaw-schema.grpc-web@v1",
                    "zeroclaw-schema",
                    "zeroclaw-schema",
                    vec!["assistant.ghostbridge.tech"],
                    BackendSpec::Grpc {
                        host: "0.0.0.0".into(),
                        port: 8090,
                        service_name: "zeroclaw.ZeroclawService".into(),
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);

        // Both tags produce routes (different tags), but the duplicate
        // subdomain is stripped from the second route.
        let grpc_bridge = routes
            .xray_routes
            .iter()
            .find(|r| r.tag == "grpc-bridge")
            .expect("grpc-bridge route exists");
        assert!(grpc_bridge
            .subdomains
            .contains(&"assistant.ghostbridge.tech".to_string()));

        let schema_route = routes
            .xray_routes
            .iter()
            .find(|r| r.tag == "zeroclaw-schema")
            .expect("zeroclaw-schema route exists");
        assert!(
            schema_route.subdomains.is_empty(),
            "duplicate subdomain should be stripped from second route"
        );
    }

    #[test]
    fn should_skip_route_when_all_subdomains_claimed() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.first@v1",
                    "first",
                    "first",
                    vec!["only.ghostbridge.tech"],
                    BackendSpec::Tcp {
                        host: "127.0.0.1".into(),
                        port: 8000,
                    },
                ),
                registry_entry(
                    "exp.service.second@v1",
                    "second",
                    "second",
                    vec!["only.ghostbridge.tech"],
                    BackendSpec::Tcp {
                        host: "127.0.0.1".into(),
                        port: 9000,
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);

        // First route keeps the subdomain; second route is skipped entirely.
        assert_eq!(routes.xray_routes.len(), 1);
        assert_eq!(routes.xray_routes[0].tag, "first");
    }

    #[test]
    fn should_preserve_unique_subdomains_across_routes() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.cognitive-mcp@v1",
                    "cognitive-mcp",
                    "cognitive-mcp",
                    vec!["mcp.internal"],
                    BackendSpec::Grpc {
                        host: "127.0.0.1".into(),
                        port: 3003,
                        service_name: "operation.cognitive.v1.CognitiveToolService".into(),
                    },
                ),
                registry_entry(
                    "src.service.qdrant@v1",
                    "qdrant",
                    "qdrant",
                    vec!["qdrant.ghostbridge.tech"],
                    BackendSpec::Unix {
                        path: "/run/qdrant.sock".into(),
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);
        assert_eq!(routes.xray_routes.len(), 2);
    }
}

