//! Ollama client — the inference surface for Gemma.
//!
//! Gemma's gallery prompts and routing classifications are generated by the
//! Ollama-hosted model (default: `gemma3`), not hardcoded strings. This module
//! probes Ollama availability (`GET /api/tags`) and generates text via
//! `POST /api/generate`. When Ollama is unreachable, callers fall back to
//! deterministic defaults so the binary still produces output.
//!
//! Configuration mirrors `large_language_model` plugin env vars:
//!   `LLM_ENDPOINT`      (default `http://127.0.0.1:11434`)
//!   `LLM_MODEL_ID`      (default `gemma3`)

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::time::Duration;

const DEFAULT_OLLAMA_ENDPOINT: &str = "http://127.0.0.1:11434";
const DEFAULT_OLLAMA_MODEL: &str = "gemma3";
const PROBE_TIMEOUT_SECS: u64 = 3;
const GENERATE_TIMEOUT_SECS: u64 = 30;

pub struct OllamaClient {
    endpoint: String,
    model: String,
    client: reqwest::blocking::Client,
}

#[derive(Serialize)]
struct GenerateRequest<'a> {
    model: &'a str,
    prompt: &'a str,
    stream: bool,
}

#[derive(Deserialize)]
struct GenerateResponse {
    response: String,
}

#[derive(Deserialize)]
struct TagsResponse {
    models: Vec<TagModel>,
}

#[derive(Deserialize)]
struct TagModel {
    name: String,
}

impl OllamaClient {
    pub fn from_env() -> Self {
        let endpoint = std::env::var("LLM_ENDPOINT")
            .unwrap_or_else(|_| DEFAULT_OLLAMA_ENDPOINT.to_string());
        let model =
            std::env::var("LLM_MODEL_ID").unwrap_or_else(|_| DEFAULT_OLLAMA_MODEL.to_string());
        let client = reqwest::blocking::Client::builder()
            .timeout(Duration::from_secs(GENERATE_TIMEOUT_SECS))
            .build()
            .unwrap_or_else(|_| reqwest::blocking::Client::new());
        Self {
            endpoint,
            model,
            client,
        }
    }

    pub fn endpoint(&self) -> &str {
        &self.endpoint
    }

    pub fn model(&self) -> &str {
        &self.model
    }

    /// Probe Ollama by listing available models. Returns the model names on
    /// success, or `None` when Ollama is unreachable.
    pub fn available_models(&self) -> Option<Vec<String>> {
        let url = format!("{}/api/tags", self.endpoint.trim_end_matches('/'));
        let probe_client = reqwest::blocking::Client::builder()
            .timeout(Duration::from_secs(PROBE_TIMEOUT_SECS))
            .build()
            .ok()?;
        let body = probe_client.get(&url).send().ok()?.text().ok()?;
        let parsed: TagsResponse = serde_json::from_str(&body).ok()?;
        Some(parsed.models.into_iter().map(|m| m.name).collect())
    }

    /// Whether the configured model is present in the Ollama instance.
    pub fn model_available(&self) -> bool {
        self.available_models()
            .map(|models| {
                models
                    .iter()
                    .any(|m| m == &self.model || m.starts_with(&format!("{}:", self.model)))
            })
            .unwrap_or(false)
    }

    /// Generate text from a prompt via `POST /api/generate`. Returns the
    /// generated text, or an error when Ollama is unreachable or returns an
    /// error status.
    pub fn generate(&self, prompt: &str) -> Result<String> {
        let url = format!("{}/api/generate", self.endpoint.trim_end_matches('/'));
        let body = GenerateRequest {
            model: &self.model,
            prompt,
            stream: false,
        };
        let response = self
            .client
            .post(&url)
            .json(&body)
            .send()
            .with_context(|| format!("failed to reach Ollama generate at {url}"))?
            .error_for_status()
            .context("Ollama generate returned an error status")?;
        let parsed: GenerateResponse = response
            .json()
            .context("failed to decode Ollama generate response")?;
        Ok(parsed.response.trim().to_string())
    }

    /// Generate text, returning a fallback when Ollama is unavailable. This is
    /// the call site for gallery prompts — never blocks the binary on an
    /// Ollama outage.
    pub fn generate_or(&self, prompt: &str, fallback: &str) -> String {
        match self.generate(prompt) {
            Ok(text) if !text.is_empty() => text,
            Ok(_) => fallback.to_string(),
            Err(e) => {
                tracing::debug!(error = %e, "Ollama generate failed; using fallback");
                fallback.to_string()
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn should_read_defaults_from_env() {
        std::env::remove_var("LLM_ENDPOINT");
        std::env::remove_var("LLM_MODEL_ID");
        let client = OllamaClient::from_env();
        assert_eq!(client.endpoint(), DEFAULT_OLLAMA_ENDPOINT);
        assert_eq!(client.model(), DEFAULT_OLLAMA_MODEL);
    }

    #[test]
    fn should_generate_or_fallback_when_ollama_unreachable() {
        std::env::set_var("LLM_ENDPOINT", "http://127.0.0.1:1"); // unreachable port
        let client = OllamaClient::from_env();
        let result = client.generate_or("test prompt", "fallback text");
        std::env::remove_var("LLM_ENDPOINT");
        assert_eq!(result, "fallback text");
    }
}

