/// Generate an LLM-backed prompt for a spec via Ollama. Asks the model to
/// describe the spec from the four Gemma perspectives (Data/Numeric,
/// Spatial/Layout, User Flow, Context/Aesthetic). Falls back to a
/// deterministic string when Ollama is unavailable so the gallery never
/// blocks on an inference outage.
fn llm_prompt_for_spec(
    ollama: &OllamaClient,
    gen_name: &str,
    idx: usize,
    plugins: &HashMap<String, Vec<PluginSchema>>,
) -> String {
    let plugin_count = plugins.len();
    let prompt = format!(
        "You are Gemma, the GhostBridge UI spec brain. Describe the '{}' interface \
         spec (variant #{}) for a network control plane dashboard. Cover four \
         perspectives in one sentence each: (1) Data/Numeric — what metrics or \
         tables are shown, (2) Spatial/Layout — the arrangement, (3) User Flow — \
         what the operator does, (4) Context/Aesthetic — the visual tone. \
         Available plugin schemas: {}. Be concise.",
        gen_name, idx, plugin_count
    );
    let fallback = format!("Gemma generated: {} #{}", gen_name, idx);
    ollama.generate_or(&prompt, &fallback)
}

